using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;

var build = BinaryLog.ReadBuild("/tmp/sv-425afcc3dfbe4b53a8b9fb7da2ed8c30/build.binlog");

// Get all errors with full detail
var errors = build.FindChildrenRecursive<Error>();
foreach (var error in errors)
{
    Console.WriteLine($"Code: {error.Code}");
    Console.WriteLine($"File: {error.File}");
    Console.WriteLine($"Line: {error.LineNumber}, Col: {error.ColumnNumber}");
    Console.WriteLine($"Text: {error.Text}");

    // Walk up to find the project
    var parent = error.Parent;
    string projectName = "unknown";
    while (parent != null)
    {
        if (parent is Project proj)
        {
            projectName = proj.Name;
            break;
        }
        parent = parent.Parent;
    }
    Console.WriteLine($"Project: {projectName}");
    Console.WriteLine("---");
}

// Check if Api had a cascading failure
Console.WriteLine("\n=== Checking Api.csproj for dependency build failure ===");
var apiProjects = build.FindChildrenRecursive<Project>().Where(p => p.Name == "Api.csproj");
foreach (var api in apiProjects)
{
    var msgs = api.FindChildrenRecursive<Message>().Where(m => 
        m.Text?.Contains("depend") == true || 
        m.Text?.Contains("Services") == true ||
        m.Text?.Contains("skipped") == true ||
        m.Text?.Contains("failed") == true);
    foreach (var m in msgs.Take(10))
    {
        Console.WriteLine($"  Api msg: {m.Text}");
    }
}
EOF
